<script setup lang="ts">
import { Button as UiButton } from '@commonplace/ui/button'
const { t, resourceLabel } = useI18n()
import { resourceTypes, type ResourceType, type NoteKind } from '#shared/wiki'
const wiki = await useWiki()
const selected = ref<NoteKind | 'all'>('all')
const resource = ref<ResourceType | 'all'>('all')
const sources = computed(() => wiki.value.notes.filter(note => note.kind === 'source'))
function selectKind(kind: NoteKind | 'all') { selected.value = kind; resource.value = 'all' }
function selectResource(type: ResourceType | 'all') { selected.value = 'source'; resource.value = type }
const filters = computed<{ value: NoteKind | 'all'; label: string }[]>(() => [{ value: 'all', label: t('allNotes') }, { value: 'concept', label: t('topics') }, { value: 'source', label: t('sources') }, { value: 'insight', label: t('insights') }])
const visible = computed(() => wiki.value.notes.filter(note => (selected.value === 'all' || note.kind === selected.value) && (resource.value === 'all' || note.resourceType === resource.value)))
const firstNote = computed(() => wiki.value.notes[0])
const graph = computed(() => wiki.value.graph())
useSeoMeta({ title: () => t('homeTitle') })
</script>
<template><WikiShell><div class="library-page"><div class="page-kicker eyebrow"><span>{{ t('garden') }}</span><span>{{ t('edition') }}</span></div><section class="library-hero"><div class="hero-copy"><div class="asterisk" aria-hidden="true">✳</div><h1>{{ t('heroFirst') }}<br /><span>{{ t('heroSecond') }}</span></h1><p>{{ t('heroIntro') }}<br />{{ t('heroDetail') }}</p><NuxtLink v-if="firstNote" :to="`/notes/${firstNote.noteId}`" class="text-link">{{ t('startThought') }} <span>↗</span></NuxtLink></div><div class="hero-graph"><div class="graph-caption eyebrow"><span>{{ t('connectedKnowledge') }}</span><NuxtLink to="/graph" :aria-label="t('openGraph')">↗</NuxtLink></div><ClientOnly><KnowledgeGraph :graph="graph" :height="275" compact @open="navigateTo(`/notes/${$event}`)" /><template #fallback><div class="graph-placeholder" /></template></ClientOnly><div class="graph-legend"><span><i class="kind-dot concept" />{{ t('topics') }}</span><span><i class="kind-dot source" />{{ t('sources') }}</span><span><i class="kind-dot insight" />{{ t('insights') }}</span></div></div></section><div class="library-stats eyebrow"><span><strong>{{ wiki.notes.length }}</strong> {{ t('notes') }}</span><span><strong>{{ graph.links.length }}</strong> {{ t('connections') }}</span><span><strong>01</strong> {{ t('growingWiki') }}</span><span class="stats-note">{{ t('smallThoughts') }}</span></div><section class="library-feed" aria-labelledby="library-title"><div class="section-heading"><h2 id="library-title">{{ t('inLibrary') }}</h2><span class="eyebrow">{{ t('recent') }} ↓</span></div><div class="filter-tabs" role="group" :aria-label="t('filterLibrary')"><UiButton variant="plain" size="inherit" v-for="filter in filters" :key="filter.value" :aria-pressed="selected === filter.value" @click="selectKind(filter.value)">{{ filter.label }}<span>{{ filter.value === 'all' ? wiki.notes.length : wiki.notes.filter(n => n.kind === filter.value).length }}</span></UiButton></div><div v-if="selected === 'all' || selected === 'source'" class="resource-filters" role="group" :aria-label="t('resourceTypes')"><UiButton variant="plain" size="inherit" :aria-pressed="selected === 'source' && resource === 'all'" @click="selectResource('all')">{{ t('allResources') }} <span>{{ sources.length }}</span></UiButton><UiButton variant="plain" size="inherit" v-for="type in resourceTypes" :key="type" :aria-pressed="resource === type" @click="selectResource(type)">{{ resourceLabel(type) }} <span>{{ sources.filter(note => note.resourceType === type).length }}</span></UiButton></div><div v-if="!visible.length" class="resource-empty" role="status"><p>{{ t('noResources') }}</p><UiButton variant="plain" size="inherit" class="text-link" @click="selectResource('all')">{{ t('showAllResources') }} ↗</UiButton></div><div class="note-grid"><NoteCard v-for="note in visible" :key="note.noteId" :note="note" /></div></section><footer class="page-footer"><span class="eyebrow">{{ t('footer') }}</span><NuxtLink to="/about">{{ t('aboutDemo') }} ↗</NuxtLink></footer></div></WikiShell></template>
